package com.gr4nt.browser.download

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableLongStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import org.json.JSONObject

enum class DlStatus { QUEUED, RUNNING, PAUSED, CONVERTING, COMPLETED, FAILED, CANCELLED }
/** FILE = http(s)/ftp file, HLS/DASH = streams converted to MP4, LOCAL = copy of a device file, BLOB = file generated by a web page. */
enum class DlKind { FILE, HLS, DASH, LOCAL, BLOB }

class DownloadItem(
    val id: String,
    val url: String,
    fileName: String,
    val kind: DlKind,
    val mime: String?,
    val userAgent: String?,
    val referer: String?,
    val threads: Int,
    /** For HLS: chosen variant playlist. For DASH: chosen video representation id. */
    val variant: String? = null,
    /** For HLS/DASH: separate audio playlist url or representation id. */
    val audio: String? = null,
    val createdAt: Long = System.currentTimeMillis()
) {
    var fileName by mutableStateOf(fileName)
    var status by mutableStateOf(DlStatus.QUEUED)
    var total by mutableLongStateOf(-1L)
    var downloaded by mutableLongStateOf(0L)
    var speed by mutableLongStateOf(0L)          // bytes / s
    var error by mutableStateOf<String?>(null)
    var path by mutableStateOf<String?>(null)    // final file
    var resumable by mutableStateOf(true)
    var activeThreads by mutableStateOf(0)
    var detail by mutableStateOf("")             // e.g. "segment 120/450"
    var etag: String? = null                       // ETag / Last-Modified, so a changed file restarts instead of corrupting

    val progress: Float get() = if (total > 0) (downloaded.toFloat() / total).coerceIn(0f, 1f) else 0f
    val isActive get() = status == DlStatus.RUNNING || status == DlStatus.QUEUED || status == DlStatus.CONVERTING

    fun toJson(): JSONObject = JSONObject()
        .put("id", id).put("url", url).put("fileName", fileName).put("kind", kind.name)
        .put("mime", mime).put("ua", userAgent).put("ref", referer).put("threads", threads)
        .put("variant", variant).put("audio", audio).put("created", createdAt)
        .put("status", status.name).put("total", total).put("downloaded", downloaded)
        .put("error", error).put("path", path).put("resumable", resumable).put("etag", etag)

    companion object {
        fun fromJson(o: JSONObject): DownloadItem {
            val d = DownloadItem(
                o.getString("id"), o.getString("url"), o.optString("fileName"),
                runCatching { DlKind.valueOf(o.optString("kind", "FILE")) }.getOrDefault(DlKind.FILE),
                o.optString("mime").ifEmpty { null }.takeIf { it != "null" },
                o.optString("ua").ifEmpty { null }.takeIf { it != "null" },
                o.optString("ref").ifEmpty { null }.takeIf { it != "null" },
                o.optInt("threads", 8),
                o.optString("variant").ifEmpty { null }.takeIf { it != "null" },
                o.optString("audio").ifEmpty { null }.takeIf { it != "null" },
                o.optLong("created")
            )
            val st = DlStatus.valueOf(o.optString("status", "PAUSED"))
            d.status = if (st == DlStatus.RUNNING || st == DlStatus.QUEUED || st == DlStatus.CONVERTING) DlStatus.PAUSED else st
            d.total = o.optLong("total", -1)
            d.downloaded = o.optLong("downloaded", 0)
            d.error = o.optString("error").ifEmpty { null }.takeIf { it != "null" }
            d.path = o.optString("path").ifEmpty { null }.takeIf { it != "null" }
            d.resumable = o.optBoolean("resumable", true)
            d.etag = o.optString("etag").ifEmpty { null }.takeIf { it != "null" }
            return d
        }
    }
}

class DrmException(msg: String) : Exception(msg)
